package com.aistock.prediction.modelcatalog;
import com.aistock.prediction.comparison.*;import static com.aistock.prediction.comparison.ComparisonTestEvidence.*;import static com.aistock.prediction.comparison.ComparisonRecords.*;import com.fasterxml.jackson.databind.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.context.annotation.*;import org.springframework.test.context.junit.jupiter.SpringJUnitConfig;import org.springframework.test.context.web.WebAppConfiguration;import org.springframework.mock.web.MockCookie;import org.springframework.web.context.WebApplicationContext;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import static org.springframework.security.test.web.servlet.setup.SecurityMockMvcConfigurers.springSecurity;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@Tag("mysql") @WebAppConfiguration @SpringJUnitConfig(ComparisonHttpTest.Config.class)
class ComparisonHttpTest {
 static class Market implements ComparisonMarketClient {final List<JsonNode> evidence=List.of(sample("SH600030",new String[]{"100","110","99"},new String[]{"1","2","3"}),sample("SH600276",new String[]{"10","11","12"},new String[]{"1","2","3"}));boolean fail;int calls;public JsonNode options(List<String> ids,String period){return M.createObjectNode().put("available",true);}public JsonNode evidence(UUID id){calls++;if(fail)throw ComparisonErrors.unavailable();return evidence.stream().filter(n->n.path("evidenceId").asText().equals(id.toString())).findFirst().orElseThrow(ComparisonErrors::invalid);}}
 @Configuration @Import({ModelHttpTest.Config.class,ComparisonController.class}) static class Config {@Bean Market market(){return new Market();}@Bean ComparisonService comparisons(ModelDatabaseFixture db,ObjectMapper mapper,Market market){return new ComparisonService(new ComparisonRepository(db.jdbc,mapper),market,mapper,Clock.fixed(Instant.parse("2026-10-13T00:00:00Z"),ZoneOffset.UTC),4);}}
 @Autowired WebApplicationContext context;@Autowired Market market;@Autowired ObjectMapper mapper;
 Input input(){return new Input(UUID.randomUUID(),List.of("SH600030","SH600276"),LocalDate.parse("2026-07-09"),LocalDate.parse("2026-10-09"),market.evidence.stream().map(n->UUID.fromString(n.path("evidenceId").asText())).toList());}
 @Test void sessionCsrfOwnerRecoveryAndStrictContracts()throws Exception{new ModelDatabaseFixture();market.fail=false;market.calls=0;var mvc=MockMvcBuilders.webAppContextSetup(context).apply(springSecurity()).build();var user=new MockCookie("AISTOCK_SESSION","user-session");var csrf=new MockCookie("XSRF-TOKEN","known-csrf");var in=input();var body=mapper.writeValueAsString(in);String uri="/api/v1/comparisons";
 mvc.perform(get(uri)).andExpect(status().isUnauthorized());mvc.perform(post(uri).cookie(user).contentType("application/json").content(body)).andExpect(status().isForbidden());mvc.perform(post(uri).cookie(user,csrf).header("Origin","https://invalid.example").header("X-XSRF-TOKEN","known-csrf").contentType("application/json").content(body)).andExpect(status().isForbidden());
 for(String bad:List.of(body.substring(0,body.length()-1)+",\"ownerId\":\"forged\"}",body.substring(0,body.length()-1)+",\"requestId\":\""+in.requestId()+"\"}",body.replace("2026-07-09","2026-99-01"))){mvc.perform(post(uri).cookie(user,csrf).header("Origin","http://127.0.0.1:15173").header("X-XSRF-TOKEN","known-csrf").contentType("application/json").content(bad)).andExpect(status().isUnprocessableEntity());}
 mvc.perform(post(uri).cookie(user,csrf).header("Origin","http://127.0.0.1:15173").header("X-XSRF-TOKEN","known-csrf").contentType("application/json").content("x".repeat(2049))).andExpect(status().isPayloadTooLarge());
 var first=mvc.perform(post(uri).cookie(user,csrf).header("Origin","http://127.0.0.1:15173").header("X-XSRF-TOKEN","known-csrf").contentType("application/json").content(body)).andExpect(status().isCreated()).andExpect(jsonPath("$.data.state").value("SUCCEEDED")).andReturn();var id=mapper.readTree(first.getResponse().getContentAsString()).path("data").path("comparisonId").asText();
 market.fail=true;mvc.perform(post(uri).cookie(user,csrf).header("Origin","http://127.0.0.1:15173").header("X-XSRF-TOKEN","known-csrf").contentType("application/json").content(body)).andExpect(status().isOk());mvc.perform(get(uri+"/"+id).cookie(user)).andExpect(status().isOk()).andExpect(jsonPath("$.data.stocks[0].maxDrawdown.value").value("10.000000"));mvc.perform(get(uri+"/"+id).cookie(new MockCookie("AISTOCK_SESSION","admin-session"))).andExpect(status().isNotFound());mvc.perform(get(uri+"/operations/"+in.requestId()).cookie(new MockCookie("AISTOCK_SESSION","admin-session"))).andExpect(status().isNotFound());mvc.perform(get(uri).cookie(user).param("owner","forged")).andExpect(status().isUnprocessableEntity());mvc.perform(get(uri).cookie(user)).andExpect(status().isOk()).andExpect(jsonPath("$.data.items[0].stocks[0].chart").doesNotExist());
 var next=input();mvc.perform(post(uri).cookie(user,csrf).header("Origin","http://127.0.0.1:15173").header("X-XSRF-TOKEN","known-csrf").contentType("application/json").content(mapper.writeValueAsString(next))).andExpect(status().isServiceUnavailable());mvc.perform(get(uri+"/operations/"+next.requestId()).cookie(user)).andExpect(status().isOk()).andExpect(jsonPath("$.data.state").value("FAILED"));market.fail=false;}
}
